#include "stdlib/math/base/special/max.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/assert/is_positive_zero.h"
#include "stdlib/constants/float64/pinf.h"

/**
* Returns the maximum value.
*
* @param x       first number
* @param y       second number
* @return        maximum value
*
* @example
* double v = stdlib_base_max( 3.14, 4.2 );
* // returns 4.2
*
* @example
* double v = stdlib_base_max( 0.0, -0.0 );
* // returns 0.0
*/
double stdlib_base_max( const double x, const double y ) {
	if ( stdlib_base_is_nan( x ) || stdlib_base_is_nan( y ) ) {
		return 0.0 / 0.0; // NaN
	}
	if ( x == STDLIB_CONSTANT_FLOAT64_PINF || y == STDLIB_CONSTANT_FLOAT64_PINF ) {
		return STDLIB_CONSTANT_FLOAT64_PINF;
	}
	if ( x == y && x == 0.0 ) {
		if ( stdlib_base_is_positive_zero( x ) ) {
			return x;
		}
		return y;
	}
	if ( x > y ) {
		return x;
	}
	return y;
}","lineStart":1,"lineEnd":56,"totalLines":56,"truncated":false}},"title":"repos\pc-lib-3456\math-base-special-max\src\main.c","time":{"start":1783813219192,"end":1783813219230}},"id":"prt_f538d9d7a00103fWMRKMyzB5D5","sessionID":"ses_0ac730c33ffen6KsJB2xOkgLut","messageID":"msg_f538d500a001ip2IcucmNj4ZXn"}}

